H.rect(boxX, boxY-boxH, boxW, boxH, { stroke: H.colors.sub, width: 3 });
// gas particles: count ~ n, speed ~ sqrt(T)
const nPart = Math.min(40, Math.max(4, Math.round(n*12)));
const speed = 40 * Math.sqrt(T/300);
